sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {
    var {payload:{item}} = event;
    var {table, encodedQuery, listTitle} = item;
    var navPayload = {
        "route": "list-view",
        "fields": {
            table
        },
        "params": {
            "query": encodedQuery,
            "listTitle":listTitle
        }
    };
    if (navPayload.fields.table == 'sn_grc_m2m_issue_item' && navPayload.params.listTitle == 'Controls') {
        navPayload.params.columns = "sn_grc_item, sn_grc_item.number, sn_grc_item.profile, sn_grc_item.state, sn_grc_item.status, sn_grc_item.ref_sn_compliance_control.exempt, sn_grc_item.owner, sn_grc_item.description";
    }

    if (navPayload.fields.table == 'sn_grc_m2m_issue_item' && (navPayload.params.listTitle == 'Risks' || navPayload.params.listTitle == 'Risk')) {
        navPayload.params.columns = "sn_grc_item, sn_grc_item.number, sn_grc_item.profile, sn_grc_item.state, sn_grc_item.status, sn_grc_item.owner, sn_grc_item.description";
    }

    if (navPayload.fields.table == 'sn_grc_m2m_issue_document' && navPayload.params.listTitle == 'Policies') {
        navPayload.params.columns = "sn_grc_document, sn_grc_document.type, sn_grc_document.owner, sn_grc_document.state, sn_grc_document.valid_from, sn_grc_document.valid_to, sn_grc_document.ref_sn_compliance_policy.compliance_score ";
    }
    if (navPayload.fields.table == 'sn_grc_m2m_issue_document' && navPayload.params.listTitle == 'Authority documents') {
        navPayload.params.columns = "sn_grc_document, sn_grc_document.ref_sn_compliance_authority_document.common_name, sn_grc_document.type, sn_grc_document.ref_sn_compliance_authority_document.compliance_score";
    }
    if (navPayload.fields.table == 'sn_grc_m2m_issue_engagement') {
        navPayload.params.columns = "sn_audit_engagement, sn_audit_engagement.number, sn_audit_engagement.engagement_type, sn_audit_engagement.assigned_to, sn_audit_engagement.state, sn_audit_engagement.audit_period_start, sn_audit_engagement.audit_period_end ";
    }

    if (navPayload.fields.table == 'sn_risk_advanced_m2m_issue_risk_event' && (navPayload.params.listTitle == 'Risk events' || navPayload.params.listTitle == 'Risk event')) {
        navPayload.params.columns = "risk_event, risk_event.number, risk_event.primary_profile, risk_event.event_type, risk_event.sub_type, risk_event.state, risk_event.discovered_on, risk_event.net_amount, risk_event.expected_loss, risk_event.non_financial_impact";
    }

    if (navPayload.fields.table == 'sn_grc_reg_change_m2m_issue_regulatory_task') {
        navPayload.params.columns = "regulatory_task, regulatory_task.assigned_to, regulatory_task.state, regulatory_task.sys_class_name";
    }

    api.emit("NAV_ITEM_SELECTED",navPayload);

}
